L["Paste this same code in Alliance > Setup in every guild of the alliance and save, once. It goes in the guild master's public note where the game allows it, and every member hands it on at login: no ambassadors, nobody in particular has to be online. The guilds find each other by themselves."] = "연합의 모든 길드에서 연합 > 설정에 같은 코드를 붙여넣고 한 번 저장하세요. 게임이 허용하는 곳에서는 길드장의 공개 쪽지에 들어가고, 모든 길드원이 접속할 때 전달합니다. 대사가 필요 없고, 특정한 사람이 접속해 있을 필요도 없습니다. 길드들은 서로를 스스로 찾습니다."
