L["An all-in-one guild suite: roster, raid attendance, cores, recruitment, professions, leadership tools and audits — all synced between guildmates who run the addon."] = "올인원 길드 도구: 명단, 공격대 출석, 코어, 모집, 전문 기술, 운영 도구, 점검 — 애드온을 쓰는 길드원끼리 모두 동기화됩니다."
L["As an officer you unlock leadership tools. In Settings -> Officer, set which guild ranks count as officers. In Settings -> Loot, choose how the guild hands out loot: free roll, Wishlist or DKP."] = "관리자는 운영 도구를 쓸 수 있습니다. 설정 -> 관리자에서 관리자로 볼 길드 등급을 정하세요. 설정 -> 전리품에서 분배 방식을 고르세요: 자유 주사위, 위시리스트, DKP."

