-- Os pontos e o sistema de loot no retail (issue #185).
L["Free roll"] = "자유 주사위"
L["Choose how your guild hands out loot: who awards an item a guildmate offers, and what an award costs."] = "길드의 전리품 분배 방식을 고르세요: 길드원이 내놓은 아이템을 누가 배정하는지, 배정에 드는 비용은 얼마인지."
L["Free roll: whoever received the item awards it to the best answer, Need before Greed, then the roll. Officers may award too."] = "자유 주사위: 아이템을 받은 사람이 가장 좋은 응답자에게 배정합니다. 입찰이 차비보다 먼저, 그다음 주사위. 관리자도 배정할 수 있습니다."
L["An officer awards an item a guildmate offers; whoever holds it then trades it to the winner."] = "길드원이 내놓은 아이템은 관리자가 배정하고, 아이템을 가진 사람이 당첨자와 거래합니다."
