-- Systems audit (#448): bans, bulk, loot, sync, moderation
L["Lift the ban on %s?"] = "%s의 차단을 해제할까요?"
L["Lift"] = "해제"
L["Share the ban on %s with your guildos.me alliance"] = "%s의 차단을 guildos.me 동맹과 공유"
L["This ban has run out: there is nothing to share."] = "이 차단은 만료되었습니다. 공유할 것이 없습니다."
L["No candidates. The /who came back empty: on WoW: Forever it may be blocked on this client."] = "후보가 없습니다. /who 결과가 비어 있습니다. WoW: Forever에서는 이 클라이언트에서 차단되었을 수 있습니다."
L["No member is waiting to be retried."] = "다시 시도할 멤버가 없습니다."
L["Usage: /gos bulk [next | skip | retry | stop]"] = "사용법: /gos bulk [next | skip | retry | stop]"
L["Retry"] = "다시 시도"
L["Retry (%d)"] = "다시 시도 (%d)"
L["Your guild rank may not do this to %s."] = "길드 등급으로는 %s에게 이 작업을 할 수 없습니다."
L["%s is already at that rank."] = "%s은(는) 이미 그 등급입니다."
L["|cffFFAA00A roll is open: the loot tests wait until it ends.|r"] = "|cffFFAA00주사위 굴림이 진행 중입니다: 전리품 테스트는 끝날 때까지 기다립니다.|r"
L["Show the loot history (awards are always recorded)"] = "전리품 기록을 표시합니다 (분배는 항상 기록됩니다)"
L["Send to guild"] = "길드에 보내기"
L["Open each profession once to share it."] = "각 전문 기술을 한 번 열어 공유하세요."
L["Whole guild database"] = "길드 전체 데이터베이스"
L["Replace this guild's whole Guild OS database with the backup and reload? This cannot be undone."] = "이 길드의 Guild OS 데이터베이스 전체를 백업으로 바꾸고 다시 불러올까요? 되돌릴 수 없습니다."
L["Guild sync is off: turn Comm System on in Settings, Modules."] = "길드 동기화가 꺼져 있습니다: 설정의 모듈에서 Comm System을 켜세요."
L["Toggle debug output, or run one diagnostic"] = "디버그 출력을 전환하거나 진단을 실행합니다"
L["%d chat alert(s) during combat: see Leadership > Chat alerts."] = "전투 중 채팅 경고 %d건: 지도부 > 채팅 경고를 확인하세요."
L["in combat: panel only"] = "전투 중: 패널에만"
L["Severity"] = "심각도"
L["Click to change: low only logs, medium alerts, high alerts with a sound."] = "클릭하여 변경: 낮음은 기록만, 보통은 경고, 높음은 소리와 함께 경고."
L["The default list in your language. Your first change makes it the one list every officer matches."] = "사용자 언어의 기본 목록입니다. 처음 변경하면 모든 간부가 쓰는 하나의 목록이 됩니다."
L["In a member's first days any link alerts and the anti-flood's limits are stricter. The join comes from the roster log: a member who joined before the addon is not a newcomer. Only officers see it."] = "가입 후 처음 며칠 동안은 어떤 링크든 경고하고 도배 방지 한도가 더 엄격합니다. 가입은 명단 기록에서 가져오며, 애드온 이전에 가입한 멤버는 신입이 아닙니다. 간부만 볼 수 있습니다."
L["Don't ask again"] = "다시 묻지 않기"
L["%s is approved. Queue their promotion in Bulk actions?"] = "%s 님이 승인되었습니다. 일괄 작업에 승급을 대기시킬까요?"
L["Queue promotion"] = "승급 대기"
L["Sent to your guild and to the Guild OS players around while enabled; one officer online sends it."] = "켜져 있는 동안 길드와 주변 Guild OS 플레이어에게 보냅니다. 접속 중인 간부 한 명이 보냅니다."
L["Kept on this client only: this game has no officer channel to share it with the other officers."] = "이 클라이언트에만 저장됩니다: 이 게임에는 다른 간부와 공유할 간부 채널이 없습니다."
L["trial"] = "수습"
L["They go to the Bulk actions queue: one click of Next each, the safe list and your rank's limits kept."] = "일괄 작업 대기열로 갑니다: 한 명당 다음을 한 번씩 클릭하며, 보호 목록과 등급 제한이 지켜집니다."

-- Master looter safety (#448, L1-L12)
L["%s did not leave the corpse: %s may have full bags or be out of range. Nothing was recorded: award it again."] = "%s이(가) 시체에서 나오지 않았습니다. %s의 가방이 가득 찼거나 거리가 너무 멉니다. 아무것도 기록되지 않았습니다. 다시 분배하세요."
L["Wait: the last item is still on its way to its winner."] = "잠시만요: 마지막 아이템이 아직 당첨자에게 가는 중입니다."
L["%s is not on the open corpse: open the one that holds it, or close the loot window to give it by trade."] = "%s은(는) 열린 시체에 없습니다. 그 아이템이 있는 시체를 열거나, 전리품 창을 닫고 거래로 주세요."
L["%s cannot take %s from this corpse (offline, outside the instance or not eligible). Nothing was recorded."] = "%s은(는) 이 시체에서 %s을(를) 받을 수 없습니다(오프라인, 인스턴스 밖 또는 자격 없음). 아무것도 기록되지 않았습니다."
L["Giving to %s..."] = "%s에게 주는 중..."

-- Loot rules and rooms (#448: L3-L9, B16, B24, B27)
L["%s awarded an item by a loot rule this client does not have: %s's counters were not changed here."] = "%s 님이 이 클라이언트에 없는 전리품 규칙으로 아이템을 분배했습니다: %s 님의 카운터는 여기서 바뀌지 않았습니다."
