L["Double ribbon. No shaking it before the time."] = "리본 두 겹. 때가 되기 전엔 흔들지 마세요."
L["Empty shelf! It wasn't me. The globes you open show here, on the site and in the game."] = "선반이 비었어요! 제가 그런 거 아니에요. 개봉한 구슬은 여기, 사이트와 게임에 나타납니다."
L["FRIMM"] = "프림"
