L["FULL"] = "가득"
L["For %s"] = "%s에게"
L["When full, the odds of rare, epic and legendary double. The Chimney at the wrapping deadline counts."] = "가득 차면 희귀, 영웅, 전설 확률이 두 배가 됩니다. 포장 마감 시점의 굴뚝이 기준입니다."
L["Full: the odds of rare, epic and legendary doubled."] = "가득: 희귀, 영웅, 전설 확률이 두 배가 되었습니다."
L["In the game: until the companion's next sync (1 to 5 min). The ceremony waits for the answer and plays once."] = "게임에서: companion의 다음 동기화까지(1~5분). 의식은 답을 기다렸다가 한 번 재생됩니다."
L["It goes to the site with the companion's next sync."] = "companion의 다음 동기화 때 사이트로 갑니다."
L["It lights after the draw and warms up with every globe wrapped."] = "추첨 후 불이 붙고 구슬이 포장될 때마다 뜨거워집니다."
L["Join the Secret Santa"] = "비밀 산타 참가"
L["Join. One per player."] = "참가하세요. 플레이어당 한 명."
L["Lights at the draw, on %s"] = "추첨일 %s에 불이 붙습니다"
L["No note."] = "쪽지 없음."
L["Noted! The draw is on %s. I shuffle the names. More or less. Trust me."] = "적어 뒀어요! 추첨은 %s입니다. 이름은 제가 섞어요. 대충요. 믿어 주세요."
L["ODDS AT THE OPENING"] = "개봉 시 확률"
L["Off: no snow, embers or rays on the Guild OS window."] = "끄기: Guild OS 창에 눈, 불씨, 빛줄기가 없습니다."
L["Off: the Winter Veil tab plays no sound."] = "끄기: 겨울맞이 탭에서 소리가 나지 않습니다."
L["One of the five scenes of the %d globe."] = "%d년 구슬의 다섯 장면 중 하나."
L["Only the globes already opened: %d of %d. A closed one stays a secret."] = "이미 개봉한 구슬만: %d/%d. 닫힌 구슬은 비밀로 남습니다."
L["Open your globe and find out its rarity."] = "구슬을 열고 희귀도를 확인하세요."
L["Pick the scene, write the note, wrap."] = "장면을 고르고, 쪽지를 쓰고, 포장하세요."
L["Preview. The rarity is drawn when they open the globe."] = "미리보기. 희귀도는 상대가 구슬을 열 때 추첨됩니다."
L["SECRET SANTA · JOINING UNTIL %s"] = "비밀 산타 · %s까지 참가"
L["See it in the Collection"] = "수집품에서 보기"
L["Snow globe · Winter Veil %d"] = "스노우볼 · 겨울맞이 %d"
L["THE NOTE"] = "쪽지"
L["THE SCENE"] = "장면"
L["The Chimney is full!"] = "굴뚝이 가득 찼어요!"
L["The Chimney · %d%%"] = "굴뚝 · %d%%"
L["The draw: you get somebody."] = "추첨: 누군가를 뽑게 됩니다."
L["The five scenes. The rarity (a base of wood, silver, gold or crystal) only comes out at the opening."] = "다섯 장면. 희귀도(나무, 은, 금, 수정 받침)는 개봉 때만 나옵니다."
L["The rarity is drawn by the site when you open it. The game only asks and shows."] = "희귀도는 개봉할 때 사이트가 추첨합니다. 게임은 요청하고 보여 줄 뿐입니다."
L["The workshop is open! Join the guild's Secret Santa and pick your globe. I wrap, you only need to want it."] = "작업장이 열렸어요! 길드 비밀 산타에 참가하고 구슬을 고르세요. 포장은 제가, 여러분은 원하기만 하면 돼요."
L["The wrapping is closed."] = "포장이 마감되었습니다."
L["UNTIL THE OPENING · %s"] = "개봉까지 · %s"
L["Until then the Chimney stays out: it lights at the draw and warms up with every globe wrapped."] = "그때까지 굴뚝은 꺼져 있습니다: 추첨 때 불이 붙고 구슬이 포장될 때마다 뜨거워집니다."
L["Up to 80 characters, no links, no @, no markdown."] = "최대 80자, 링크, @, 마크다운 불가."
