-- The Winter Veil tab, review of guildos-web#673 (caprice drawn twice, sync, clues); translations to review
L["caprice note: drawn twice"] = "정성 쪽지: 두 번 추첨"
L["Caprice note: the rarity is drawn twice and the better one stays."] = "정성 쪽지: 희귀도를 두 번 추첨해 더 좋은 쪽이 남습니다."
L["With %d characters or more and %d different letters, the rarity is drawn twice. %d to go."] = "%d자 이상, 서로 다른 글자 %d개 이상이면 희귀도를 두 번 추첨합니다. %d자 남음."
L["A caprice note needs %d different letters."] = "정성 쪽지에는 서로 다른 글자 %d개가 필요합니다."
L["%d%% of the pairs wrapped or played the event"] = "짝의 %d%%가 포장했거나 이벤트를 플레이했습니다"
L["Waiting to sync: the site does not have this wrap yet. Sync the companion."] = "동기화 대기 중: 사이트에 아직 이 포장이 없습니다. companion을 동기화하세요."
L["The wrapping closes in less than a day and the site does not have yours yet: sync the companion."] = "포장이 하루 안에 마감되는데 사이트에 아직 당신의 포장이 없습니다: companion을 동기화하세요."
